mkdir -p /tmp/gbrain-scripts && cat > /tmp/gbrain-scripts/mcp-recall.mjs <<'EOF'
import { spawn } from 'node:child_process';
import { readFileSync } from 'node:fs';
const cfg = JSON.parse(readFileSync('/harness-state/claude/.claude.json','utf8')).mcpServers.gbrain;
const p = spawn(cfg.command, cfg.args, { env: { ...process.env, ...cfg.env }, stdio: ['pipe','pipe','inherit'] });
let buf = '', pending = {};
p.stdout.on('data', d => { buf += d; let i; while ((i = buf.indexOf('\n')) >= 0) { const line = buf.slice(0,i); buf = buf.slice(i+1); if (!line.trim()) continue; const m = JSON.parse(line); if (m.id && pending[m.id]) { pending[m.id](m); delete pending[m.id]; } } });
let n = 0; const rpc = (method, params) => new Promise(r => { const id = ++n; pending[id] = r; p.stdin.write(JSON.stringify({ jsonrpc:'2.0', id, method, params })+'\n'); });
const init = await rpc('initialize', { protocolVersion:'2025-06-18', capabilities:{}, clientInfo:{ name:'install-check', version:'1' } });
console.log('server:', JSON.stringify(init.result?.serverInfo));
p.stdin.write(JSON.stringify({ jsonrpc:'2.0', method:'notifications/initialized' })+'\n');
const tl = await rpc('tools/list', {});
console.log('tools:', tl.result.tools.map(t=>t.name).join(', '));
const r = await rpc('tools/call', { name:'recall', arguments:{ entity:'gbrain-install-check', _meta:{ hot_memory:'off' } } });
console.log('recall isError:', r.result?.isError ?? r.error);
console.log((r.result?.content||[]).map(c=>c.text).join('\n').slice(0,800));
p.kill();
EOF
cd /tmp && timeout 90 node /tmp/gbrain-scripts/mcp-recall.mjs
